import { PREFIXES } from '../../../model/parse.js';
import type { Quad, Term } from '../../../model-boundary.js';
import { ODRL, termOf } from './anchor.js';
import type { ReadStore } from './anchor.js';

const RDF = PREFIXES.rdf as string;
const XSD = PREFIXES.xsd as string;

export const ODRL_LEFT = `${ODRL}leftOperand`;
export const ODRL_OP = `${ODRL}operator`;
export const ODRL_RIGHT = `${ODRL}rightOperand`;
export const ODRL_RIGHT_REF = `${ODRL}rightOperandReference`;
export const ODRL_PURPOSE = `${ODRL}purpose`;

export const SLOT_PREDS = [ODRL_LEFT, ODRL_OP, ODRL_RIGHT];

export const SLOT_DATATYPES = [`${XSD}date`, `${XSD}dateTime`, `${XSD}integer`,
  `${XSD}boolean`, `${XSD}duration`];

export interface SlotRight {
  kind: 'literal' | 'iri';
  value: string;
  lang: string;
  datatype: string;
}

export interface SlotValues {
  left: string;
  operator: string;
  right: SlotRight;
}

function slotObjects(store: ReadStore | null, term: Term | null, pred: string): Term[] {
  if (!store || !term) return [];
  return store.getQuads(term, termOf(pred), null, null).map((q) => q.object);
}

/** `setConstraint` replaces the right-hand value with ONE value, so a compound
 *  one must be left alone or the rest is cleared and its nodes orphaned. */
export function compoundValue(store: ReadStore | null, term: Term | null): boolean {
  const objs = slotObjects(store, term, ODRL_RIGHT);
  if (objs.length > 1) return true;
  if (slotObjects(store, term, ODRL_RIGHT_REF).length) return true;
  const o = objs[0];
  if (o && o.termType === 'BlankNode') return true;
  return !!(o && o.termType !== 'Literal' && store
    && store.getQuads(o, termOf(`${RDF}first`), null, null).length);
}

export function slotValues(
  store: ReadStore | null, term: Term | null, curie: (iri: string) => string | null,
): SlotValues {
  const iriOf = (pred: string): string => {
    const o = slotObjects(store, term, pred)[0];
    return o && o.termType === 'NamedNode' ? (o.value || '') : '';
  };
  const r = slotObjects(store, term, ODRL_RIGHT)[0] || null;
  const isLit = !!r && r.termType === 'Literal';
  const dt = (r as { datatype?: { value?: string } } | null)?.datatype?.value || '';
  return {
    left: iriOf(ODRL_LEFT),
    operator: iriOf(ODRL_OP),
    right: {
      kind: r && r.termType === 'NamedNode' ? 'iri' : 'literal',
      value: (r && r.termType === 'NamedNode')
        ? (curie(r.value || '') || r.value || '') : ((r && r.value) || ''),
      lang: isLit ? ((r as { language?: string }).language || '') : '',
      datatype: isLit && dt && !/#string$/.test(dt) ? dt : '',
    },
  };
}

export function slotsEditable(
  store: ReadStore | null, term: Term | null,
  checks: { quadsInEditSource: (q: Quad[]) => boolean; editable: (t: Term) => boolean },
): boolean {
  if (!store || !term) return false;
  return SLOT_PREDS.every((pred) => {
    const own = store.getQuads(term, termOf(pred), null, null);
    return own.length ? checks.quadsInEditSource(own) : checks.editable(term);
  });
}

export type RowKind = 'slots' | 'anchor' | 'group' | 'fallback';

export function rowKind(c: {
  technicalMeasure?: boolean; logical?: string | null; children?: unknown[];
  slots?: unknown;
} | null): RowKind {
  if (!c) return 'fallback';
  if (c.technicalMeasure) return 'anchor';
  if (c.slots) return 'slots';
  if (c.logical && (c.children || []).length) return 'group';
  return 'fallback';
}

export function purposeBindingTerm(store: ReadStore | null, ruleTerm: Term | null): Term | null {
  if (!store || !ruleTerm) return null;
  for (const a of store.getQuads(ruleTerm, termOf(`${ODRL}action`), null, null)) {
    for (const r of store.getQuads(a.object, termOf(`${ODRL}refinement`), null, null)) {
      const left = store.getQuads(r.object, termOf(ODRL_LEFT), null, null)[0];
      if (left && left.object.value === ODRL_PURPOSE) return r.object;
    }
  }
  return null;
}
