// REUSE IN PLACE. The ↻ of a section heading opens, at the INSERTION PLACE of
// that section, a short list of candidate rows: every named rule of that kind
// from the loaded sources, drawn as a dimmed ghost of its real row plus a
// small origin chip. Clicking one lays the link through the existing reuse
// route — this file is presentation, not a second data path.
import { createEffect, createMemo, createSignal, For, on, onCleanup, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { text } from '../../../stores/view.js';
import type { Term } from '../../../model-boundary.js';
import type { Core } from './core.js';
import { termOf } from './anchor.js';
import { closeReuse, openKey, reuseKey } from './reuse-open.js';
import type { SectionAddHookCtx } from '../../shared/edit-hook.jsx';
import '../edit.css';

export interface Candidate {
  iri: string;
  label: string;
  curie: string | null;
  provenance: string[];
  tier: number;
}

const TIER = { sameSource: 0, otherPolicy: 1, loose: 2 };

/** Which named graph a node was written in — its source, in one string. */
function graphOf(core: Core, term: Term | null): string {
  if (!term) return '';
  const g = core.graph();
  if (!g) return '';
  for (const q of g.getQuads(term, null, null, null)) {
    if (q.graph && q.graph.value) return q.graph.value;
  }
  return '';
}

// THE ORDER IS THE ANSWER TO "which of these is probably mine": first what
// lives in the same source as this policy, then what hangs on another policy,
// then what hangs on nothing yet — the register-shaped candidates.
export function rank(
  rows: { iri: string; label: string; curie: string | null; provenance: string[] }[],
  sameSource: (iri: string) => boolean,
): Candidate[] {
  return rows
    .map((r) => ({
      ...r,
      tier: sameSource(r.iri) ? TIER.sameSource
        : (r.provenance.length ? TIER.otherPolicy : TIER.loose),
    }))
    .sort((a, b) => (a.tier - b.tier) || a.label.localeCompare(b.label, 'nl'));
}

export function matches(c: Candidate, filter: string): boolean {
  const q = filter.trim().toLowerCase();
  if (!q) return true;
  return `${c.label} ${c.curie || ''} ${c.provenance.join(' ')}`.toLowerCase().includes(q);
}

export interface ReuseListProps {
  core: Core;
  ctx: SectionAddHookCtx;
  candidates: () => { iri: string; label: string; curie: string | null; provenance: string[] }[];
  onPick: (iri: string) => void;
}

export function SectionReuseList(props: ReuseListProps): JSX.Element {
  const term = createMemo(() => termOf(props.ctx.pol));
  const key = () => reuseKey(term()?.value || '', props.ctx.kind);
  const isOpen = () => openKey() === key();

  const [filter, setFilter] = createSignal('');
  const [active, setActive] = createSignal(0);
  let listEl: HTMLUListElement | undefined;

  const ranked = createMemo<Candidate[]>(() => {
    if (!isOpen()) return [];
    const mine = graphOf(props.core, term());
    return rank(props.candidates(),
      (iri) => !!mine && graphOf(props.core, { termType: 'NamedNode', value: iri } as Term) === mine);
  });
  const shown = createMemo(() => ranked().filter((c) => matches(c, filter())));

  // A fresh opening starts clean, and a filter that shrinks the list must not
  // leave the marker pointing past its end.
  createEffect(on(isOpen, (on_) => { if (on_) { setFilter(''); setActive(0); } }));
  createEffect(() => { if (active() >= shown().length) setActive(0); });
  createEffect(() => { if (isOpen() && listEl) listEl.focus(); });

  const idOf = (i: number) => `reuse-pick-${props.ctx.kind}-${i}`;

  // A card that leaves takes its open list with it, or the key would stay set
  // and the next ↻ on that section would toggle it SHUT.
  onCleanup(() => { if (isOpen()) closeReuse(); });

  const close = (): void => {
    const back = listEl?.closest('.offer-group, .agr-group')
      ?.querySelector(`.card-${props.ctx.kind}-reuse`) as HTMLElement | null;
    closeReuse();
    back?.focus();
  };

  const pick = (c: Candidate): void => {
    props.onPick(c.iri);
  };

  const move = (step: number): void => {
    const n = shown().length;
    if (!n) return;
    setActive((((active() + step) % n) + n) % n);
    const row = listEl?.querySelector(`#${idOf(active())}`) as HTMLElement | null;
    // jsdom gives elements no scrollIntoView, and a keyboard walk must not
    // break on a platform that cannot scroll.
    if (row && typeof row.scrollIntoView === 'function') {
      row.scrollIntoView({ block: 'nearest' });
    }
  };

  const onKey = (e: KeyboardEvent): void => {
    if (e.key === 'ArrowDown') { e.preventDefault(); move(1); return; }
    if (e.key === 'ArrowUp') { e.preventDefault(); move(-1); return; }
    if (e.key === 'Home') { e.preventDefault(); setActive(0); return; }
    if (e.key === 'End') { e.preventDefault(); setActive(Math.max(0, shown().length - 1)); return; }
    if (e.key === 'Enter') {
      e.preventDefault();
      const c = shown()[active()];
      if (c) pick(c);
      return;
    }
    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); close(); return; }
    if (e.key === 'Backspace') { e.preventDefault(); setFilter((v) => v.slice(0, -1)); return; }
    // TYPE TO FILTER, native-listbox style: no search widget, the list has the
    // focus and the keystrokes narrow it.
    if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
      e.preventDefault();
      setFilter((v) => v + e.key);
    }
  };

  // Clicking elsewhere tidies the list away. On the document, in the capture
  // phase, so a click on another card closes this one before that card acts.
  createEffect(() => {
    if (!isOpen() || typeof document === 'undefined') return;
    const away = (e: Event): void => {
      const t = e.target as Node | null;
      if (t && listEl && listEl.contains(t)) return;
      if (t && (t as HTMLElement).closest?.(`.card-${props.ctx.kind}-reuse`)) return;
      closeReuse();
    };
    document.addEventListener('pointerdown', away, true);
    onCleanup(() => document.removeEventListener('pointerdown', away, true));
  });

  return (
    <Show when={isOpen()}>
      <ul
        ref={(el: HTMLUListElement) => { listEl = el; }}
        class="reuse-picks"
        role="listbox"
        tabindex="0"
        aria-label={text('edit.reuseChoose')}
        aria-activedescendant={shown().length ? idOf(active()) : undefined}
        on:keydown={onKey}
      >
        <Show
          when={shown().length}
          fallback={<li class="reuse-pick-none muted">{text('edit.reuseNoMatch')}</li>}
        >
          <For each={shown()}>{(c, i) => (
            <li
              id={idOf(i())}
              class={'reuse-pick' + (i() === active() ? ' is-active' : '')}
              role="option"
              aria-selected={i() === active() ? 'true' : 'false'}
              on:click={() => { setActive(i()); pick(c); }}
              on:pointerenter={() => setActive(i())}
            >
              <span class={`method ${props.ctx.kind} ghost-badge`}>{text('edit.reusePick')}</span>
              <span class="reuse-pick-name">{c.label}</span>
              <Show when={c.curie}>{(cu) => (
                <span class="reuse-pick-curie mono muted">{cu()}</span>
              )}</Show>
              <span class="reuse-pick-origin muted">
                {c.provenance.length
                  ? text('edit.reuseOrigin', { policy: c.provenance.join(', ') })
                  : text('edit.reuseLoose')}
              </span>
            </li>
          )}</For>
        </Show>
        <Show when={filter()}>
          <li class="reuse-pick-filter muted" aria-live="polite">
            {text('edit.reuseFilter', { text: filter(), n: shown().length })}
          </li>
        </Show>
      </ul>
    </Show>
  );
}
